def _is_prime_ref(n: int) -> bool:
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def _expected(interval1, interval2):
    l = max(interval1[0], interval2[0])
    r = min(interval1[1], interval2[1])
    if l > r:
        return "NO"
    length = r - l
    return "YES" if _is_prime_ref(length) else "NO"

@given(st.integers(min_value=-30, max_value=30), st.integers(min_value=0, max_value=30))
def test_contained_interval_length_determines_answer(s, ln):
